window.docContents[158].resolve({"/LindenstraussPolynomials/Construction/#LindenstraussPolynomials___diag_seqP_succ_seqx":{"contents":"P_{k+1}(x_k) = (1 + α_k) P_k(x_k). \n\n","context":"","header":"LindenstraussPolynomials.diag_seqP_succ_seqx","id":"/LindenstraussPolynomials/Construction/#LindenstraussPolynomials___diag_seqP_succ_seqx"},"/LindenstraussPolynomials/Substitution/#mod-doc-LindenstraussPolynomials___Substitution-1-0":{"contents":"The substitutions and the averaging operators\n\nFor \\|u\\|=\\|f\\|=f(u)=1 and t\\in[0,1], the substitution\nS_{u,f}(t)\\,x = (1-t)\\,x + t\\,f(x)\\,u\n(eq:substitution) maps the unit ball into itself and fixes u. Averaging a polynomial over these substitutions gives\n\\mathcal R_{u,f}P(x) = \\int_0^1 P\\bigl(S_{u,f}(t)\\,x\\bigr)\\,dt,\nand this module proves the properties of \\mathcal R_{u,f} the construction needs (eq:Rproperties, eq:expansion, eq:Rfinite).\n\n\n","context":"","header":"LindenstraussPolynomials.Substitution","id":"/LindenstraussPolynomials/Substitution/#mod-doc-LindenstraussPolynomials___Substitution-1-0"}});